'use strict';
const DAY=86400000;
// All calendar math uses UTC to avoid daylight-saving and timezone offsets.
function parseDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))throw Error('Preencha uma data válida.');const [y,m,d]=value.split('-').map(Number);const t=Date.UTC(y,m-1,d);const a=new Date(t);if(y<1900||y>2200||a.getUTCFullYear()!==y||a.getUTCMonth()!==m-1||a.getUTCDate()!==d)throw Error('Confira a data informada.');return t;}
function todayValue(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function dateText(ms){return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long',year:'numeric',timeZone:'UTC'}).format(ms);}
function estimateDue(date,cycle){return date+(280+cycle-28)*DAY;}
function gestationalAge(date,reference){const days=Math.round((reference-date)/DAY);if(days<0)throw Error('A data de referência deve ser igual ou posterior à última menstruação.');if(days>300)throw Error('O intervalo ultrapassa 42 semanas e 6 dias. Confira as datas com sua equipe de saúde.');return {weeks:Math.floor(days/7),days:days%7};}
const tool=document.querySelector('[data-tool]')?.dataset.tool;
const ref=document.querySelector('#reference');if(ref)ref.value=todayValue();
const inputDate=document.querySelector('#date');if(inputDate)inputDate.max=todayValue();
function showResult(title,detail){const r=document.querySelector('#result');r.replaceChildren();const strong=document.createElement('strong');strong.textContent=title;r.append(strong);const p=document.createElement('p');p.textContent=detail;r.append(p);}
document.querySelector('#tool-form')?.addEventListener('submit',event=>{event.preventDefault();try{if(tool==='nomes-bebe'){renderNames();return;}const date=parseDate(inputDate.value);const today=parseDate(todayValue());if(date>today)throw Error('A última menstruação não pode estar no futuro.');let cycle=28;if(document.querySelector('#cycle')){cycle=Number(document.querySelector('#cycle').value);if(!Number.isInteger(cycle)||cycle<21||cycle>35)throw Error('Use um ciclo inteiro entre 21 e 35 dias. Para outros ciclos, procure orientação individual.');}if(tool==='calculadora-parto'){if(today-date>300*DAY)throw Error('Esta data está há mais de 42 semanas e 6 dias. Confira a última menstruação.');showResult(dateText(estimateDue(date,cycle)),'Data provável do parto. É uma estimativa, não uma previsão exata. Confirme a datação no pré-natal.');}if(tool==='semanas-gravidez'){const age=gestationalAge(date,parseDate(ref.value));showResult(`${age.weeks} semanas e ${age.days} ${age.days===1?'dia':'dias'}`,'Idade gestacional estimada pela última menstruação na data de referência escolhida.');}if(tool==='periodo-fertil'){const ov=date+(cycle-14)*DAY;showResult(`${dateText(ov-5*DAY)} a ${dateText(ov+DAY)}`,`Janela fértil aproximada do ciclo informado. Ovulação estimada: ${dateText(ov)}. Próxima menstruação estimada: ${dateText(date+cycle*DAY)}. Não use para evitar gravidez.`);}}catch(e){showResult('Confira os dados',e.message);}});
const babyNames=['Alice','Ana','André','Antônio','Arthur','Augusto','Aurora','Beatriz','Bento','Bernardo','Bianca','Bruno','Caetano','Caio','Camila','Catarina','Cecília','Clara','Daniel','Dante','Davi','Diana','Eduardo','Elisa','Eloá','Emanuel','Enzo','Estela','Eva','Felipe','Fernanda','Flora','Francisco','Gabriel','Gael','Giovana','Guilherme','Helena','Henrique','Hugo','Isabel','Isadora','Joana','João','Joaquim','José','Júlia','Laura','Lavínia','Leonardo','Letícia','Levi','Lia','Lívia','Lorenzo','Luana','Lucas','Luísa','Luna','Maitê','Manuela','Maria','Marina','Mateus','Melissa','Miguel','Nina','Noah','Olívia','Otávio','Pedro','Rafael','Raul','Ravi','Samuel','Sara','Sofia','Theo','Valentina','Vicente'];
function renderNames(){const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const q=normalize(document.querySelector('#name-search').value.trim()),size=document.querySelector('#name-size').value;const matches=babyNames.filter(n=>normalize(n).startsWith(q)&&(size==='all'||(size==='short'?n.length<=4:n.length>=5)));const holder=document.querySelector('#names');holder.replaceChildren(...matches.map(n=>{const e=document.createElement('div');e.className='name';e.textContent=n;return e;}));showResult(`${matches.length} ${matches.length===1?'nome encontrado':'nomes encontrados'}`,matches.length?'Uma seleção para começar a conversar.':'Tente outra inicial ou escolha todos os tamanhos.');}
if(tool==='nomes-bebe')renderNames();
if(tool==='mala-maternidade'){
const key='amor-berco-mala-v1';const items=['Documento com foto e cartão SUS ou convênio','Caderneta da gestante e exames solicitados','Plano de parto, se houver','Roupas confortáveis para a internação e a saída','Roupas íntimas e absorventes para o pós-parto','Chinelos e itens de higiene pessoal','Medicamentos em uso, conforme orientação da equipe','Celular e carregador','Roupinhas do bebê adequadas ao clima','Fraldas e itens de higiene pedidos pela maternidade','Roupa e itens pessoais do acompanhante','Bebê-conforto instalado para a saída de carro'];
let selected=[];try{const stored=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(stored))selected=stored.filter(x=>Number.isInteger(x)&&x>=0&&x<items.length);}catch(e){document.querySelector('#storage-status').textContent='Não foi possível recuperar a lista. Você pode marcar e imprimir os itens nesta sessão.';}
const list=document.querySelector('#checklist');items.forEach((text,i)=>{const label=document.createElement('label');label.className='check-row';const input=document.createElement('input');input.type='checkbox';input.checked=selected.includes(i);input.value=i;const span=document.createElement('span');span.textContent=text;label.append(input,span);list.append(label);input.addEventListener('change',update);});
function update(){const checked=[...list.querySelectorAll('input:checked')].map(e=>Number(e.value));document.querySelector('#check-status').textContent=`${checked.length} de ${items.length} itens preparados`;document.querySelector('#check-progress').value=checked.length;try{if(checked.length)localStorage.setItem(key,JSON.stringify(checked));else localStorage.removeItem(key);}catch(e){document.querySelector('#storage-status').textContent='O navegador bloqueou o salvamento. A lista funciona nesta sessão; imprima para guardar.';}}
document.querySelector('#reset-check').addEventListener('click',()=>{list.querySelectorAll('input').forEach(e=>e.checked=false);update();});update();
}
function downloadCSV(rows){const text='\uFEFFInício;Duração (segundos);Intervalo entre inícios (segundos)\r\n'+rows.map(r=>`${new Date(r.start).toISOString()};${Math.round(r.duration/1000)};${r.interval===null?'':Math.round(r.interval/1000)}`).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='amor-de-berco-contracoes.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
if(tool==='contador-contracoes'){
let start=null,tick=null,rows=[];const button=document.querySelector('#contraction-toggle'),timer=document.querySelector('#timer'),state=document.querySelector('#timer-state');
const duration=ms=>{const n=Math.floor(ms/1000);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;};
function render(){const log=document.querySelector('#contraction-log');log.replaceChildren();if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=3;td.textContent='Seu registro aparecerá aqui.';tr.append(td);log.append(tr);}for(const r of [...rows].reverse()){const tr=document.createElement('tr');[new Date(r.start).toLocaleTimeString('pt-BR'),duration(r.duration),r.interval===null?'—':duration(r.interval)].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td);});log.append(tr);}document.querySelector('#download-log').disabled=rows.length===0;}
button.addEventListener('click',()=>{if(start===null){start=Date.now();button.textContent='Terminar contração';state.textContent='Contração em andamento. Toque ao terminar.';tick=setInterval(()=>timer.textContent=duration(Date.now()-start),200);}else{const end=Date.now();rows.push({start,duration:Math.max(0,end-start),interval:rows.length?start-rows[rows.length-1].start:null});clearInterval(tick);timer.textContent=duration(end-start);start=null;button.textContent='Iniciar contração';state.textContent='Contração registrada. Aguarde a próxima para iniciar novamente.';render();}});
document.querySelector('#clear-log').addEventListener('click',()=>{if((rows.length||start!==null)&&!confirm('Apagar o histórico desta sessão e cancelar a contração em andamento?'))return;clearInterval(tick);start=null;rows=[];timer.textContent='00:00';state.textContent='Registro limpo.';button.textContent='Iniciar contração';render();});
document.querySelector('#download-log').addEventListener('click',()=>downloadCSV(rows));
window.addEventListener('beforeunload',e=>{if(start!==null||rows.length){e.preventDefault();e.returnValue='';}});
}
